const core = require('@gltf-transform/core');
async function test() {
  const doc = new core.Document();
  const buf = doc.createBuffer('main');
  const scene = doc.createScene('s');
  const acc = doc.createAccessor('pos')
    .setArray(new Float32Array([0,0,0, 1,0,0, 0,1,0]))
    .setType(core.Accessor.Type.VEC3)
    .setBuffer(buf);
  const prim = doc.createPrimitive().setAttribute('POSITION', acc);
  const mesh = doc.createMesh('m').addPrimitive(prim);
  const node = doc.createNode('n').setMesh(mesh);
  scene.addChild(node);
  const io = new core.NodeIO();
  const jsonDoc = await io.writeJSON(doc);
  // Convert to single JSON string for .gltf
  // resources contains buffer URIs -> Uint8Array
  console.log('json keys:', Object.keys(jsonDoc.json));
  console.log('resources keys:', Object.keys(jsonDoc.resources));
  // For embedded gltf, we'd need to base64 encode the buffers
  // Or just stringify the json part
  const jsonStr = JSON.stringify(jsonDoc.json);
  console.log('JSON length:', jsonStr.length);
}
test().catch(e => console.error(e));
"

